{
  "items": [
    {
      "title": "Destatis – Migration Between Germany and Foreign Countries (1950–2025)",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Society-Environment/Population/Migration/Tables/migration-year-01.html",
      "justification": "Official dataset from Germany's Federal Statistical Office (Destatis) covering annual immigration, emigration, and net migration. Includes complete data for 2010–2019, distinguishing German and non-German citizens. Particularly useful for analyzing migration trends during the 2010s, including the sharp increase in immigration in 2015 and subsequent changes."
    },
    {
      "title": "Destatis GENESIS-Online – International Migration by Nationality (Table 12711-0007)",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/url/b2eb042c",
      "justification": "Official German statistical database containing annual immigration, emigration, and net migration figures broken down by nationality. Covers 2000 onward, including the entire 2010–2019 period. Particularly valuable for examining the countries of citizenship of migrants arriving in or departing from Germany, including Syrian, Turkish, Polish, Romanian, and other nationalities."
    },
    {
      "title": "Eurostat – Immigration by Age Group, Sex and Citizenship (migr_imm8)",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/products-datasets/-/migr_imm8",
      "justification": "European Union statistical dataset containing annual immigration figures by age, sex, and citizenship. Germany's observations can be selected for 2010–2019. Particularly useful for analyzing the demographic composition of immigration and comparing Germany's migration patterns with those of other European countries."
    },
    {
      "title": "Eurostat – Emigration by Age Group, Sex and Country of Next Usual Residence (migr_emi3nxt)",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/migr_emi3nxt/default/table?category=migr.migr_cit.migr_emi&lang=en",
      "justification": "Official Eurostat dataset recording emigration by demographic characteristics and destination country. Includes Germany and historical observations from the 2010s. Useful for studying departures from Germany, identifying major destination countries, and analyzing changes in migration outflows throughout the decade."
    },
    {
      "title": "Eurostat – International Migration and Citizenship Statistics",
      "url_or_doi": "https://ec.europa.eu/eurostat/en/web/migration-asylum/international-migration-citizenship/information-data",
      "justification": "Official Eurostat data portal providing access to multiple datasets on immigration, emigration, migrant populations, and citizenship acquisition. Includes historical series covering 2010–2019. Useful for researchers seeking standardized migration indicators and comparable data across European countries."
    },
    {
      "title": "IAB-BAMF-SOEP Survey of Refugees in Germany (2016–2019)",
      "url_or_doi": "https://fdz.iab.de/en/pd_hd/iab-bamf-soep-survey-of-refugees-version-1619-v1/",
      "justification": "Representative longitudinal survey jointly conducted by the Institute for Employment Research (IAB), the Federal Office for Migration and Refugees (BAMF), and the German Socio-Economic Panel (SOEP). Covers refugees who arrived in Germany during the 2010s, with survey observations from 2016–2019. Contains detailed individual-level information on migration histories, employment, education, language acquisition, integration, and living conditions. Particularly relevant for studying the experiences of refugees who arrived during the 2015–2016 migration crisis. Access to microdata is subject to research data access conditions."
    },
    {
      "title": "DIW Berlin – IAB-BAMF-SOEP Migration and Refugee Survey Data Editions",
      "url_or_doi": "https://www.diw.de/en/diw_01.c.795950.en/",
      "justification": "Official dataset catalogue from the German Institute for Economic Research (DIW Berlin), providing access information for migration and refugee survey datasets, including editions covering 2016–2019. Particularly useful for studying immigrant integration, labor-market participation, household characteristics, educational attainment, and socioeconomic outcomes among migrants and refugees in Germany."
    },
    {
      "title": "German Socio-Economic Panel – SOEP-Core (1984–2020)",
      "url_or_doi": "https://www.diw.de/en/diw_01.c.838573.en/edition/soep-core_v37at__data_1984-2020__add-on__area_types.html",
      "justification": "Large-scale longitudinal household survey covering Germany's population, including individuals with migration backgrounds. Contains observations throughout 2010–2019 and information on employment, income, education, household composition, and demographic characteristics. Useful for comparing migrants and non-migrants and examining the socioeconomic integration of immigrant populations during the 2010s. Research data access conditions apply."
    },
    {
      "title": "Destatis – Migration Flows and International Migration Statistics",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Society-Environment/Population/Migration/_node.html",
      "justification": "Official German statistical portal providing access to detailed migration statistics, including international arrivals and departures, countries of origin and destination, and regional migration patterns. Historical data include the 2010s. Useful for identifying additional downloadable statistical tables and investigating geographical differences in migration across Germany."
    },
    {
      "title": "Eurostat Migration Data for 2010–2019 – MigMod",
      "url_or_doi": "https://a-wis.github.io/MigMod/reference/mig_data.html",
      "justification": "Research-oriented dataset derived from publicly available Eurostat migration statistics, specifically covering 2010–2019. Includes migration-related information for Germany and other European countries. Particularly useful for computational analysis, cross-country comparisons, and statistical modeling of migration patterns during the decade. This is a secondary research dataset rather than the original Eurostat database."
    }
  ]
}
